    'FW2': (43, dict(type=(1, 1), id=(2, 10), shipped=(11, 18), weight=(19, 26), status=(27, 27)),
            Fraction(1, 100), 'ymd'),
    'FW3': (41, dict(id=(1, 9), shipped=(10, 16), type=(17, 17), weight=(18, 24), status=(25, 25)),
            FACTOR['lb'] / 10, 'yj'),
}
HARBOR_STATUS = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
                 'RET': 'returned', 'HLD': 'held'}
FW_STATUS = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def read_bytes(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    m = re.search(rb'^#\s*charset\s*:\s*([\w.\-]+)', b[:2000], re.M | re.I)
    enc = m.group(1).decode('ascii') if m else 'utf-8'
    return b.decode(enc)


def rec_type(s):
    s = (s or '').strip().lower()
    if s[:1] == 'v':
        return 'void'
    if s[:1] in ('c', 'a'):
        return 'correction'
    return 'new'


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def id_number(s):
    m = re.fullmatch(r'\s*SH\W*(\d+)\s*', s or '', re.I)
    return int(m.group(1)) if m else None


def parse_weight(text, unit, depot):
    """text may carry its own unit suffix; returns kg Fraction."""
    t = (text or '').strip()
    m = re.fullmatch(r'(.*?)\s*(kg|g|lb|oz)', t, re.I)
    if m:
        t, unit = m.group(1), m.group(2).lower()
    if depot == 'west':
        t = t.replace('.', '').replace(',', '.')
    else:
        t = t.replace(',', '')
    return Fraction(t) * FACTOR[unit]


def parse_date(s, form):
    s = (s or '').strip()
    f = re.sub(r'\s+', '', form or '').upper()
    if f == 'SERIAL' or (f not in ('ISO', 'YMD') and re.fullmatch(r'\d{5}', s) and not re.search(r'[./-]', f)):
        return datetime.date(1899, 12, 31) + datetime.timedelta(days=int(s) - 1)
    if f in ('ISO', 'YMD', 'YYYY-MM-DD'):
        y, mo, d = re.split(r'\D', s[:10])[:3]
    else:
        a, b, c = re.split(r'\D+', s)[:3]
        order = re.sub(r'[^A-Z]', '', f.replace('YYYY', 'Y').replace('DD', 'D').replace('MM', 'M'))
        if order in ('DMY', 'DMYY'):
            d, mo, y = a, b, c
        elif order == 'MDY':
            mo, d, y = a, b, c
        else:
            y, mo, d = a, b, c
    return datetime.date(int(y), int(mo), int(d))


def parse_time(s):
    """ISO time with offset, or 'DD Mon YYYY', or date -> UTC date."""
    s = s.strip()
    m = re.fullmatch(r'(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})', s)
    if m:
        return datetime.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    if 'T' in s or ' ' in s:
        dt = datetime.datetime.fromisoformat(s.replace(' ', 'T', 1))
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc)
        return dt.date()
    return datetime.date.fromisoformat(s)


# each reader returns (seq, [records]); record = (type, number, date|None, kg|None, status|None)

def read_xml(path, depot):
    root = ET.fromstring(read_bytes(path))
    seq = int(root.get('seq', 0))
    base = root.get('weight-unit', 'kg').lower()
    out = []
    for s in root.iter('shipment'):
        n = id_number(s.get('id'))
        if n is None:
            continue
        typ = rec_type(s.get('type'))
        if typ == 'void':
            out.append((typ, n, None, None, None))
            continue
        sh = s.get('shipped')
        if s.find('shipped') is not None:
            sh = s.find('shipped').text
        w = s.find('weight')
        unit = (w.get('unit') or base).lower()
        out.append((typ, n, parse_time(sh), parse_weight(w.text, unit, depot),
                    norm_status(s.findtext('status'))))
    return seq, out


def read_json(path, depot):
    seq = 0
    out = []
    for line in decode(read_bytes(path)).split('\n'):
        if not line.strip():
            continue
        v = json.loads(line)
        for o in (v if isinstance(v, list) else [v]):
            if 'meta' in o:
                seq = int(o['meta'].get('seq', seq))
                continue
            n = id_number(o.get('id'))
            if n is None:
                continue
            typ = rec_type(o.get('kind'))
            if typ == 'void':
                out.append((typ, n, None, None, None))
                continue
            wk = [k for k in o if k.startswith('weight_')][0]
            out.append((typ, n, parse_time(o['shipped_at']),
                        parse_weight(str(o[wk]), wk[7:].lower(), depot), norm_status(o['status'])))
    return seq, out


def logical_rows(text, quoting):
    """Yield ('comment', line) or ('row', raw)."""
    buf = None
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if buf is None:
            if not line.strip():
                continue
            if line.startswith('#'):
                yield 'comment', line
                continue
            buf = line
        else:
            buf += '\n' + line
        if not quoting or buf.count('"') % 2 == 0:
            yield 'row', buf
            buf = None
    if buf is not None:
        yield 'row', buf


def read_delimited(path, depot):
    text = decode(read_bytes(path))
    delim = DELIM[depot]
    quoting = delim == ','
    cols = COLS[depot]
    cid, ctype, cdate, cw, cst = FIELDS[depot]
    seq = 0
    unit = 'kg'
    dform = BASE_DATE[depot]
    hdr = None
    out = []
    for kind, raw in logical_rows(text, quoting):
        if kind == 'comment':
            m = re.match(r'#\s*([^:=]+?)\s*[:=]\s*(.*)$', raw)
            if m:
                name = re.sub(r'\s+', ' ', m.group(1).lower())
                val = m.group(2).strip()
                if name == 'seq':
                    seq = int(val)
                elif name in ('unit', 'weight unit'):
                    unit = val.split()[0].lower()
                elif name in ('dates', 'date format'):
                    dform = val.split()[0]
            else:
                m = re.search(r'seq=(\d+)', raw)
                if m:
                    seq = int(m.group(1))
            continue
        row = next(csv.reader([raw], delimiter=delim)) if quoting else raw.split(delim)
        row = [x.strip() for x in row] if not quoting else row
        if row and all(x.strip() in cols for x in row):
            hdr = [x.strip() for x in row]
            continue
        if hdr is None:
            continue
        rowunit = None
        if len(row) == len(hdr) + 1:
            rowunit = row[hdr.index(cw) + 1].strip().lower()
            del row[hdr.index(cw) + 1]
        if len(row) != len(hdr):
            continue
        d = dict(zip(hdr, row))
        n = id_number(d.get(cid))
        if n is None:
            continue
        typ = rec_type(d.get(ctype))
        if typ == 'void':
            out.append((typ, n, None, None, None))
            continue
        u = 'kg' if cw == 'gross_kg' else (rowunit or unit)
        st = d[cst]
        if depot == 'harbor':
            st = HARBOR_STATUS.get(st.strip().upper(), st)
        out.append((typ, n, parse_date(d[cdate], dform), parse_weight(d[cw], u, depot), norm_status(st)))
    return seq, out


def read_fixed(path, depot):
    text = decode(read_bytes(path))
    seq = 0
    layout = None
    by_len = {v[0]: k for k, v in FW.items()}
    out = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if line.startswith('\x0c') or not line.strip():
            continue
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', line)
            if m:
                layout = m.group(1)
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m:
                seq = int(m.group(1))
            continue
        if 'SHIPMENT LISTING' in line:
            continue
        name = by_len.get(len(line), layout)
        if name not in FW:
            continue
        length, f, wf, dk = FW[name]
        line = line.ljust(length)
        g = {k: line[a - 1:b] for k, (a, b) in f.items()}
        n = id_number(g['id'])
        if n is None:
            continue
        typ = rec_type(g['type'])
        if typ == 'void':
            out.append((typ, n, None, None, None))
            continue
        sh = g['shipped']
        if dk == 'ymd':
            date = datetime.date(int(sh[:4]), int(sh[4:6]), int(sh[6:8]))
        else:
            date = datetime.date(int(sh[:4]), 1, 1) + datetime.timedelta(days=int(sh[4:]) - 1)
        out.append((typ, n, date, int(g['weight']) * wf, FW_STATUS.get(g['status'].strip(), '?')))
    return seq, out


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        if depot not in PRIORITY:
            continue
        if depot == 'central':
            r = read_xml(p, depot)
        elif depot == 'north':
            r = read_json(p, depot)
        elif depot == 'south':
            r = read_fixed(p, depot)
        else:
            r = read_delimited(p, depot)
        exports.setdefault(depot, []).append((r[0], name, r[1]))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for typ, n, date, kg, st in recs:
                if typ == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = (date, kg, st)
                elif typ == 'correction':
                    cur[n] = (date, kg, st)
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    depots = {d: [0, Fraction(0)] for d in exports}
    months = {}
    handovers = 0
    owners = {}
    for depot in PRIORITY:
        for n in current.get(depot, {}):
            owners.setdefault(n, []).append(depot)
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        date, kg, st = current[ds[0]][n]
        if st in ('delivered', 'delivered_late'):
            depots[ds[0]][0] += 1
            depots[ds[0]][1] += kg
            m = months.setdefault('%04d-%02d' % (date.year, date.month), [0, Fraction(0)])
            m[0] += 1
            m[1] += kg

    def r2(x):
        c = x * 100
        return float(Fraction((c.numerator * 2 + c.denominator) // (c.denominator * 2), 100))

    result = {
        'depots': {d: {'shipments': v[0], 'total_kg': r2(v[1])} for d, v in sorted(depots.items())},
        'months': {k: {'shipments': v[0], 'total_kg': r2(v[1])} for k, v in sorted(months.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(result, f, indent=2)
        f.write('\n')


if __name__ == '__main__':
    main()
